
const API_BASE_URL = (import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000').replace(/\/$/, '');

// Read the XSRF token generated by Laravel Sanctum
const getXsrfToken = () => {
  const cookie = document.cookie
    .split('; ')
    .find((row) => row.startsWith('XSRF-TOKEN='));

  return cookie
    ? decodeURIComponent(cookie.split('=').slice(1).join('='))
    : '';
};

// Initialize CSRF protection before login
export const initializeCsrf = async () => {
  const response = await fetch(`${API_BASE_URL}/sanctum/csrf-cookie`, {
    credentials: 'include',
    headers: {
      Accept: 'application/json',
    },
  });

  if (!response.ok) {
    throw new Error('Could not initialize CSRF protection');
  }
};

// Send requests to Laravel
export const apiRequest = async (
  endpoint: string,
  options: RequestInit = {}
) => {
  const method = (options.method || 'GET').toUpperCase();

  const headers = new Headers(options.headers);
  headers.set('Accept', 'application/json');

  if (options.body) {
    headers.set('Content-Type', 'application/json');
  }

  if (!['GET', 'HEAD', 'OPTIONS'].includes(method)) {
    const token = getXsrfToken();

    if (token) {
      headers.set('X-XSRF-TOKEN', token);
    }
  }

  // Combine caller cancellation with a real timeout. Passing options.signal directly
  // previously disabled the timeout and could leave requests pending indefinitely.
  const controller = new AbortController();
  const onAbort = () => controller.abort();
  if (options.signal?.aborted) controller.abort();
  options.signal?.addEventListener('abort', onAbort, { once: true });
  const timeout = setTimeout(() => controller.abort(), 15000);
  let response: Response;
  try {
    response = await fetch(`${API_BASE_URL}${endpoint}`, {
      ...options,
      signal: controller.signal,
      method,
      headers,
      credentials: 'include',
    });
  } catch (error) {
    if (controller.signal.aborted && !options.signal?.aborted) {
      throw new Error('انتهت مهلة الاتصال بالخادم (15 ثانية)');
    }
    throw error;
  } finally {
    clearTimeout(timeout);
    options.signal?.removeEventListener('abort', onAbort);
  }

  const data = await response.json().catch(() => null);

  if (!response.ok) {
    throw new Error(
      data?.message || `Request failed with status ${response.status}`
    );
  }

  return data;
};
